const std = @import("std"); const http = std.http; const mem2 = std.mem; const safe = @import("nt-safe-guar.zig"); const urln = @import("ut-urlz-norm.zig"); const rend = @import("nt-brow-rend.zig"); const cdp2 = @import("nt-brow-cdpz.zig");
const CF = .{ .lnez = 1 << 20, .evnt = "text/event-stream", .join = 1500, .tick = 10 };
pub const Opts = struct { time_mill: u32 = 30000, fra2: u32 = 1000, priv: bool = false, uagt: []const u8 = "scra/0.1.0", repe: bool = false };
const Shrz = struct { gpaz: std.mem.Allocator, iozz: std.Io, urlz: []u8, opts: Opts, lock: std.atomic.Value(bool) = .init(false), fram: std.ArrayList([]u8) = .empty, done: std.atomic.Value(bool) = .init(false), stop: std.atomic.Value(bool) = .init(false), refs: std.atomic.Value(u32) = .init(2), code: std.atomic.Value(u16) = .init(0), ssez: std.atomic.Value(bool) = .init(false),
fn lckz(self: *Shrz) void { while (self.lock.cmpxchgWeak(false, true, .acquire, .monotonic) != null) {} }
fn unlz(self: *Shrz) void { self.lock.store(false, .release); }
fn full(self: *Shrz) bool { self.lckz(); defer self.unlz(); return self.fram.items.len >= self.opts.fra2; }
fn push(self: *Shrz, tex2: []const u8) void { const cpzz = self.gpaz.dupe(u8, tex2) catch return; self.lckz(); defer self.unlz(); if (self.fram.items.len >= self.opts.fra2) { self.gpaz.free(cpzz); return; } self.fram.append(self.gpaz, cpzz) catch self.gpaz.free(cpzz); }
fn relz(self: *Shrz) void { if (self.refs.fetchSub(1, .acq_rel) == 1) { for (self.fram.items) |frzz| self.gpaz.free(frzz); self.fram.deinit(self.gpaz); const gpaz = self.gpaz; gpaz.free(self.urlz); gpaz.destroy(self); } } };
fn ctypOfzz(head: http.Client.Response.Head) []const u8 { var iter = head.iterateHeaders(); while (iter.next()) |item| { if (std.ascii.eqlIgnoreCase(item.name, "content-type")) return item.value; } return ""; }
fn once(shrz: *Shrz) !u32 { const gpaz = shrz.gpaz; const part = try urln.urlzSpli(shrz.urlz); try safe.hostChek(shrz.iozz, part.host, shrz.opts.priv); const uriz = std.Uri.parse(shrz.urlz) catch return error.BadUrl; var clnt: http.Client = .{ .allocator = gpaz, .io = shrz.iozz }; defer clnt.deinit(); var hdr3 = [_]http.Header{.{ .name = "Accept", .value = "text/event-stream, application/x-ndjson, application/json" }}; var req2 = try clnt.request(.GET, uriz, .{ .redirect_behavior = .unhandled, .keep_alive = false, .headers = .{ .user_agent = .{ .override = shrz.opts.uagt } }, .extra_headers = &hdr3 }); defer req2.deinit(); req2.accept_encoding = @splat(false); req2.accept_encoding[@backingInt(http.ContentEncoding.identity)] = true; try req2.sendBodiless(); var redb: [4096]u8 = undefined; var resp = try req2.receiveHead(&redb); const code: u16 = @backingInt(resp.head.status); shrz.code.store(code, .release); if (code < 200 or code >= 300) return error.BadStatus; const ssez = std.ascii.findIgnoreCase(ctypOfzz(resp.head), CF.evnt) != null; shrz.ssez.store(ssez, .release); const tbuf = try gpaz.alloc(u8, CF.lnez); defer gpaz.free(tbuf); const rdr3 = resp.reader(tbuf); var curr: std.ArrayList(u8) = .empty; defer curr.deinit(gpaz); var got2: u32 = 0;
while (!shrz.stop.load(.acquire) and !shrz.full()) { const line = rdr3.takeDelimiterInclusive('\n') catch break; const trmz = mem2.trimEnd(u8, line, "\r\n"); if (!ssez) { if (trmz.len > 0) { shrz.push(trmz); got2 += 1; } continue; } if (trmz.len == 0) { if (curr.items.len > 0) { shrz.push(curr.items); got2 += 1; curr.clearRetainingCapacity(); } continue; } if (trmz[0] == ':') continue; if (mem2.startsWith(u8, trmz, "data:")) { var vlzz = trmz[5..]; if (vlzz.len > 0 and vlzz[0] == ' ') vlzz = vlzz[1..]; if (curr.items.len > 0) curr.append(gpaz, '\n') catch {}; curr.appendSlice(gpaz, vlzz) catch {}; } } if (ssez and curr.items.len > 0 and !shrz.stop.load(.acquire)) { shrz.push(curr.items); got2 += 1; } return got2; }
fn work(shrz: *Shrz) void { while (!shrz.stop.load(.acquire) and !shrz.full()) { const got2 = once(shrz) catch break; if (got2 == 0 or shrz.ssez.load(.acquire) or !shrz.opts.repe) break; } shrz.done.store(true, .release); shrz.relz(); }
pub fn ssezRead(gpaz: std.mem.Allocator, aren: std.mem.Allocator, iozz: std.Io, urlz: []const u8, opts: Opts) ![]const []const u8 { const shrz = try gpaz.create(Shrz); shrz.* = .{ .gpaz = gpaz, .iozz = iozz, .urlz = try gpaz.dupe(u8, urlz), .opts = opts }; const thr2 = std.Thread.spawn(.{}, work, .{shrz}) catch { shrz.relz(); shrz.relz(); return error.Unexpected; }; thr2.detach(); const dead = cdp2.nowzMill(iozz) + opts.time_mill; while (!shrz.done.load(.acquire) and !shrz.full() and cdp2.nowzMill(iozz) < dead) std.Io.sleep(iozz, .fromMilliseconds(CF.tick), .awake) catch {}; shrz.stop.store(true, .release); const jend = cdp2.nowzMill(iozz) + CF.join; while (!shrz.done.load(.acquire) and cdp2.nowzMill(iozz) < jend) std.Io.sleep(iozz, .fromMilliseconds(CF.tick), .awake) catch {}; const code = shrz.code.load(.acquire); var outp: std.ArrayList([]const u8) = .empty; shrz.lckz(); for (shrz.fram.items) |frzz| outp.append(aren, aren.dupe(u8, frzz) catch continue) catch {}; shrz.unlz(); shrz.relz(); if (outp.items.len == 0 and (code < 200 or code >= 300) and code != 0) return error.BadStatus; return outp.toOwnedSlice(aren); }
pub fn wszzRead(rndz: *rend.Rndr, aren: std.mem.Allocator, urlz: []const u8, opts: Opts) ![]const []const u8 { if (!rndz.avai()) return error.NoBrowser; const pgz2 = rndz.pageGetz() catch return error.NoBrowser; const conn = pgz2.conn; var outp: std.ArrayList([]const u8) = .empty; _ = conn.callJson(aren, "Network.enable", "", 5000) catch { rndz.reset(); return error.BrowFail; }; _ = conn.callJson(aren, "Page.enable", "", 5000) catch { rndz.reset(); return error.BrowFail; }; var from: usize = conn.evzzCoun(); const prmz = try std.json.Stringify.valueAlloc(aren, .{ .url = urlz }, .{}); _ = conn.callJson(aren, "Page.navigate", prmz, 10000) catch { rndz.reset(); return error.BrowFail; }; const dead = cdp2.nowzMill(rndz.iozz) + opts.time_mill; while (outp.items.len < opts.fra2) { const left = dead - cdp2.nowzMill(rndz.iozz); if (left <= 0) break; const mes2 = (conn.evzzWait(aren, "Network.webSocketFrameReceived", &from, @intCast(left)) catch { rndz.reset(); return error.BrowFail; }) orelse break; const valu = std.json.parseFromSliceLeaky(std.json.Value, aren, mes2, .{}) catch continue; if (valu != .object) continue; const prms = valu.object.get("params") orelse continue; if (prms != .object) continue; const resp = prms.object.get("response") orelse continue; if (resp != .object) continue; const payz = resp.object.get("payloadData") orelse continue; if (payz == .string) try outp.append(aren, payz.string); } return outp.toOwnedSlice(aren); }
pub fn jso2(aren: std.mem.Allocator, fram: []const []const u8) ![]u8 { var outp: std.ArrayList(u8) = .empty; for (fram) |frzz| { if (std.json.validate(aren, frzz) catch false) { try outp.appendSlice(aren, frzz); } else { try outp.appendSlice(aren, try std.json.Stringify.valueAlloc(aren, frzz, .{})); } try outp.append(aren, '\n'); } return outp.toOwnedSlice(aren); }
